package fr.proutlost.director.api.model;
import java.util.*;
/** Contract transition guards. Recovery evidence is mandatory; these guards perform no domain work. */
public final class StateTransitions {
 private StateTransitions() {}
 @SafeVarargs
 private static <E extends Enum<E>> boolean in(E to,E... values){for(E value:values)if(value==to)return true;return false;}
 public static boolean allows(EventState from,EventState to){
  if(from==to)return false;
  if(to==EventState.RECOVERING)return !in(from,EventState.SUCCEEDED,EventState.PARTIAL,EventState.ABORTED_SAFE,EventState.FAILED_SAFE);
  if(to==EventState.CLEANING)return in(from,EventState.RUNNING,EventState.RESOLVING,EventState.RECOVERING);
  return switch(from){case PROPOSED -> in(to,EventState.RESERVED,EventState.ABORTED_SAFE);case RESERVED -> in(to,EventState.PREPARING,EventState.ABORTED_SAFE);case PREPARING -> in(to,EventState.READY,EventState.ABORTED_SAFE,EventState.FAILED_SAFE);case READY -> in(to,EventState.RUNNING,EventState.ABORTED_SAFE);case RUNNING -> to==EventState.RESOLVING;case RESOLVING,CLEANING -> in(to,EventState.SUCCEEDED,EventState.PARTIAL,EventState.ABORTED_SAFE,EventState.FAILED_SAFE);case RECOVERING -> in(to,EventState.READY,EventState.RESOLVING,EventState.ABORTED_SAFE,EventState.FAILED_SAFE);default -> false;};
 }
 public static boolean allows(StepState from,StepState to){return switch(from){case WAITING -> in(to,StepState.PREPARED,StepState.SKIPPED_SAFE,StepState.CONFLICT,StepState.FAILED);case PREPARED -> in(to,StepState.APPLIED,StepState.SKIPPED_SAFE,StepState.CONFLICT,StepState.FAILED);case APPLIED -> in(to,StepState.CONFIRMED,StepState.CONFLICT,StepState.FAILED);default -> false;};}
 public static boolean allows(DisasterStage from,DisasterStage to,boolean sufficientWarning){if(to==DisasterStage.ABORTED_SAFE)return from!=DisasterStage.RESOLVED&&from!=DisasterStage.ABORTED_SAFE;return switch(from){case WATCH -> to==DisasterStage.WARN;case WARN -> to==DisasterStage.IMPACT&&sufficientWarning;case IMPACT -> to==DisasterStage.STABILIZE;case STABILIZE -> to==DisasterStage.RESOLVED;default -> false;};}
 public static boolean allows(MutationState from,MutationState to){return switch(from){case PLANNED -> to==MutationState.PREPARED_DURABLE;case PREPARED_DURABLE -> in(to,MutationState.APPLIED_UNCONFIRMED,MutationState.COMPENSATING,MutationState.CONFLICT_ISOLATED);case APPLIED_UNCONFIRMED -> in(to,MutationState.VERIFIED,MutationState.COMPENSATING,MutationState.YIELDED,MutationState.CONFLICT_ISOLATED);case VERIFIED -> in(to,MutationState.COMMITTED,MutationState.COMPENSATING);case COMMITTED -> to==MutationState.COMPENSATING;case COMPENSATING -> in(to,MutationState.ROLLED_BACK,MutationState.YIELDED,MutationState.CONFLICT_ISOLATED);default -> false;};}
 public static boolean allows(UniqueStatus from,UniqueStatus to,boolean prepared,boolean absenceProven){return from==UniqueStatus.RESERVED&&(in(to,UniqueStatus.SPENT_CONFIRMED,UniqueStatus.SPENT_POSSIBLE)||(to==UniqueStatus.RELEASED_BEFORE_EFFECT&&(!prepared||absenceProven)));}
 public static boolean allows(RequestStatus from,RequestStatus to,RequestKind kind,boolean confirmedFact){if(in(from,RequestStatus.FULFILLED,RequestStatus.CONFLICT,RequestStatus.CANCELLED,RequestStatus.EXPIRED)||from==to)return false;if(to==RequestStatus.FULFILLED)return confirmedFact;if(to==RequestStatus.EXPIRED)return kind==RequestKind.PREFER;return in(to,RequestStatus.WAITING_CONTEXT,RequestStatus.WAITING_SAFETY,RequestStatus.SCHEDULED,RequestStatus.EXECUTING,RequestStatus.CONFLICT,RequestStatus.CANCELLED);}
 public static boolean allows(RunControl from,RunControl to){if(from==to)return false;if(to==RunControl.READ_ONLY_SAFE)return true;return switch(from){case BOOTSTRAP -> to==RunControl.RECOVERING;case RECOVERING -> to==RunControl.RUNNING;case RUNNING -> in(to,RunControl.PAUSED,RunControl.DRAINING);case PAUSED -> in(to,RunControl.RUNNING,RunControl.DRAINING);default -> false;};}
 public static boolean allows(OwnershipDisposition from,OwnershipDisposition to){if(from==to)return false;return switch(from){case DIRECTOR_ACTIVE -> in(to,OwnershipDisposition.DIRECTOR_DURABLE,OwnershipDisposition.SHARED_EXPLICIT,OwnershipDisposition.YIELDED_TO_PLAYER,OwnershipDisposition.RELEASED,OwnershipDisposition.CONFLICT_ISOLATED);case DIRECTOR_DURABLE,SHARED_EXPLICIT -> in(to,OwnershipDisposition.YIELDED_TO_PLAYER,OwnershipDisposition.RELEASED,OwnershipDisposition.CONFLICT_ISOLATED);default -> false;};}
 public static boolean allows(ChainState from,ChainState to){if(from==to)return false;return switch(from){case WAITING -> in(to,ChainState.READY,ChainState.ABORTED_SAFE);case READY -> in(to,ChainState.ACTIVE,ChainState.SUSPENDED,ChainState.ABORTED_SAFE);case ACTIVE -> in(to,ChainState.WAITING,ChainState.SUSPENDED,ChainState.BRANCHED,ChainState.SETTLED_AS_WORLD_STATE,ChainState.COMPLETED,ChainState.ABORTED_SAFE);case SUSPENDED,BRANCHED -> in(to,ChainState.READY,ChainState.SETTLED_AS_WORLD_STATE,ChainState.ABORTED_SAFE);default -> false;};}
 public static boolean allows(EntityPhase from,EntityPhase to){if(from==to)return false;if(to==EntityPhase.UNLOADED)return in(from,EntityPhase.PRESENT,EntityPhase.MOVING,EntityPhase.SETTLED,EntityPhase.CLEANING);if(to==EntityPhase.ADOPTED)return in(from,EntityPhase.PRESENT,EntityPhase.MOVING,EntityPhase.SETTLED,EntityPhase.UNLOADED);return switch(from){case RESERVED -> to==EntityPhase.SPAWN_INTENT_DURABLE;case SPAWN_INTENT_DURABLE -> in(to,EntityPhase.PRESENT,EntityPhase.CLEANING);case PRESENT -> in(to,EntityPhase.MOVING,EntityPhase.SETTLED,EntityPhase.CLEANING);case MOVING -> in(to,EntityPhase.SETTLED,EntityPhase.CLEANING);case SETTLED -> to==EntityPhase.CLEANING;case CLEANING -> to==EntityPhase.REMOVED;case UNLOADED -> in(to,EntityPhase.PRESENT,EntityPhase.MOVING,EntityPhase.SETTLED,EntityPhase.CLEANING);default -> false;};}
}
